def state_abstraction(grid):
    # Define valid movements (up, down, left, right)
    directions = [(0, -1), (0, 1), (-1, 0), (1, 0)]

    # Get all possible states
    states = []
    for i in range(len(grid)):
        for j in range(len(grid[0])):
            if grid[i][j] != None:
                state = (i, j)
                states.append(state)

    # Group adjacent states together
    grouped_states = {}
    for state in states:
        group = set()
        stack = [state]

        while stack:
            current_state = stack.pop()
            if grid[current_state[0]][current_state[1]] != None:
                group.add(current_state)

                for direction in directions:
                    next_state = (current_state[0] + direction[0], current_state[1] + direction[1])

                    # Check if the next state is within the grid boundaries
                    if 0 <= next_state[0] < len(grid) and 0 <= next_state[1] < len(grid[0]):
                        stack.append(next_state)

        grouped_states[tuple(group)] = tuple(group)

    return list(grouped_states.keys())

